Test Case:
@Test
  public void testQuoted_byChar() {
    Parser<String> scanner = Scanners.quoted('<', '>');
    assertStringScanner(mode, scanner, "<abc123>");
    assertFailure(mode, scanner, "<a", 1, 3);
  }
